import { useRef, useState, type FormEvent } from 'react';
import { JxAlert, JxButton, JxInputField, JxSelect, JxSwitch } from '@jinx-ui/react';

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

const ROLES = [
  { value: 'viewer', label: 'Наблюдатель', meta: 'только чтение' },
  { value: 'editor', label: 'Редактор', meta: 'правит контент' },
  { value: 'admin', label: 'Администратор', meta: 'управляет командой' },
];

export default function TeamInviteForm() {
  const [email, setEmail] = useState('');
  const [touched, setTouched] = useState(false);
  const [role, setRole] = useState('editor');
  const [notify, setNotify] = useState(true);
  const [sending, setSending] = useState(false);
  const [invited, setInvited] = useState<string | null>(null);
  const submitRef = useRef<HTMLButtonElement>(null);

  const isValid = EMAIL_PATTERN.test(email.trim());
  const errorText = touched && !isValid ? 'Укажите адрес вида name@example.com' : undefined;

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setTouched(true);
    if (!isValid || sending) return;
    setSending(true);
    setInvited(email.trim());
    setEmail('');
    setTouched(false);
    setSending(false);
  };

  const dismiss = () => {
    setInvited(null);
    submitRef.current?.focus();
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-gap, 16px)', maxWidth: '420px' }}>
      {invited !== null && (
        <div style={{ display: 'flex', alignItems: 'flex-start', gap: 'var(--jx-gap, 8px)' }}>
          <div style={{ flex: '1 1 auto', minWidth: 0 }}>
            <JxAlert intent="success" title="Приглашение отправлено" role="status">
              {notify ? `Письмо ушло на ${invited}.` : `Участник ${invited} добавлен без уведомления.`}
            </JxAlert>
          </div>
          <JxButton variant="ghost" size="sm" iconOnly aria-label="Закрыть сообщение" onClick={dismiss}>
            ✕
          </JxButton>
        </div>
      )}

      <form onSubmit={submit} noValidate style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-gap, 16px)' }}>
        <JxInputField
          label="Электронная почта"
          type="email"
          name="email"
          required
          autoComplete="email"
          placeholder="name@example.com"
          value={email}
          onChange={(event) => setEmail(event.target.value)}
          onBlur={() => setTouched(true)}
          helperText="Пригласим одного человека — адрес рабочей почты"
          errorText={errorText}
        />

        <JxSelect
          label="Роль в команде"
          placeholder="Выберите роль"
          options={ROLES}
          value={role}
          onValueChange={setRole}
        />

        <JxSwitch
          label="Отправить уведомление на почту"
          name="notify"
          checked={notify}
          onChange={(event) => setNotify(event.target.checked)}
        />

        <div style={{ display: 'flex', gap: 'var(--jx-gap, 8px)' }}>
          <JxButton ref={submitRef} type="submit" variant="primary" disabled={!isValid || sending}>
            {sending ? 'Отправляем…' : 'Отправить приглашение'}
          </JxButton>
        </div>
      </form>
    </div>
  );
}

